/* 投稿のあとの案内（11/7）：公開・下書き・予約のあとに、次にできることを短く出す */
/* 左の列（11/7）：並び替えとマイライブラリーは外し（本文の上の並び替え・プロフィールのメニュー・右の「ライブラリーを開く」で使える）、
   右上にあった冷蔵庫くんとプロフィールを「＋知識を届ける」の下に置く */
.side-me{display:grid;gap:8px}.side-me[hidden]{display:none}.side-me-btn{display:flex;align-items:center;gap:12px;width:100%;border:0;background:transparent;text-align:left;padding:9px 12px;border-radius:12px;font-weight:700;color:#35322e;min-height:54px}.side-me-btn:hover,.side-me-btn[aria-expanded="true"]{background:var(--soft);color:#bd6100}.side-me-btn img,.side-me-avatar{width:36px;height:36px;border-radius:50%;object-fit:cover;flex:none;border:1px solid var(--line);background:#fff}.side-me-avatar{display:grid;place-items:center;background:#292724;color:#fff;font-weight:800;overflow:hidden;font-size:15px}.side-me-avatar img{width:100%;height:100%;border:0;object-fit:cover}.side-me-icon{background:#fff4e6;color:#bd6100;border-color:#f2c48a}.side-me-label{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
@media(max-width:760px){.side-me{display:flex;gap:8px;margin:12px 0 12px}.side-me-btn{flex:1 1 0;min-width:0;min-height:48px;padding:6px 10px;border:1px solid var(--line);background:#fff;gap:8px}.side-me-btn img,.side-me-avatar{width:32px;height:32px}#sideMe{display:none!important}}
/* 投稿カードの操作（11/7 オーナー）。「この知識が生んだ価値」の下に、左から 🫶役に立った 🤝改善案を届ける ✍️議題にする 📮シェア 💭届いた声・変更履歴 😖削除 の絵文字1列。押すと今までと同じ画面が開く。スマホもパソコンも同じ（パソコンも 11/7 オーナー） */.card .actions{display:flex;flex-wrap:wrap;gap:6px;justify-content:space-between;overflow:visible}.card .actions>button{order:9;flex:1 1 0;min-width:0;min-height:48px;padding:6px 0;font-size:0;line-height:1;margin:0;grid-column:auto}.card .actions>button::before{content:attr(data-emoji);font-size:24px}.card .actions>[data-react="good"]{order:1}.card .actions>[data-react="change"]{order:2}.card .actions>[data-react="propose"]{order:3}.card .actions>.share-btn{order:4}.card .actions>.acts-more{display:block;order:5}.card .actions>.delete-btn{order:6;color:inherit;border-color:#efc4bf}.card .actions>.acts-more[aria-expanded="true"]{border-color:#f2a04b;background:#fff7eb}.card .actions .acts-menu{display:none}.card .actions.more-open::after{content:"";order:7;flex-basis:100%;height:0}.card .actions.more-open .acts-menu{display:flex;order:8;flex:1 1 40%;gap:8px}.card .actions.more-open .acts-menu>button{flex:1 1 0;min-height:44px;font-size:14px}/* パソコン・タブレット（11/7）：絵文字は決まった大きさの四角を左から並べる（横いっぱいに伸ばさない） */@media(min-width:761px){.card .actions{justify-content:flex-start;gap:8px}.card .actions>button{flex:0 0 64px}}/* スマホ（11/7）：「この知識が生んだ価値」の数字（役に立った・改善参加・採用済み）は出さない。検索は「知識を探す」へ移した（ここは何か入っているときだけ出す。入っていると消せるように） */@media(max-width:760px){.impact .stats{display:none}.search:has(input:placeholder-shown){display:none}}/* スマホ（11/7 オーナー）：上を軽くして投稿に目が行くように。並び（おすすめ・新着…）は1段にまとめ、テーマはその最後の「テーマ ▾」で開く。並びの列は上に貼り付け、下へ読み進めると隠れ、少し戻すと出る。パソコン・タブレットは今までどおり */.theme-toggle{display:none}@media(max-width:760px){body{overflow-x:clip!important}.filters{position:sticky;top:0;z-index:6;background:var(--paper);margin:0 -14px;padding:8px 14px;border-bottom:1px solid var(--line);transition:transform .2s ease}html.filters-away .filters{transform:translateY(-110%)}.filters .theme-toggle{display:inline-block}html.themes-open .filters .theme-toggle{background:#fff8ee;border-color:#f2ad62;color:#b75c00}.themes{display:none}html.themes-open .themes{display:flex;flex-wrap:nowrap;overflow-x:auto;padding:10px 0 4px}}
.after-save{background:#fff8ee;border:1px solid #f2ce9c;border-radius:14px;padding:14px 16px;margin:0 0 16px;line-height:1.7}.after-save b{display:block;margin-bottom:4px}.after-save p{margin:0 0 8px;color:#6b5a45;font-size:13px}.after-save .row{display:flex;flex-wrap:wrap;gap:8px}.after-save button{border:1px solid #f2a04b;background:#fff;color:#ad5700;border-radius:10px;padding:9px 14px;min-height:42px;font-weight:800}.after-save .x{border:0;color:#8a7a68;margin-left:auto}
/* 詳しく整理する（任意）：Knowledge Lab と同じ分類・経験の詳細・AI同意（初期は同意しない） */
.lab-more{border:1px solid var(--line);border-radius:12px;padding:12px 14px;margin:14px 0;background:#fdfcfb}.lab-more summary{cursor:pointer;font-weight:800;color:#555;min-height:28px;line-height:28px}.lab-more textarea{min-height:90px!important}.field select{border:1px solid #dfd8ce;background:#fdfcfb;border-radius:12px;padding:12px;font:inherit;max-width:100%}.lab-axis{border-top:1px solid var(--line);padding:8px 0}.lab-axis summary{cursor:pointer;font-size:13px;font-weight:800;color:#555;min-height:32px;line-height:32px}.lab-axis summary small{margin-left:8px;color:#bd6100;font-weight:700}.lab-axis .opts{padding:4px 0 6px}.lab-facets .opts{display:flex;flex-wrap:wrap;gap:6px}.lab-facets label{display:inline-flex;align-items:center;gap:5px;border:1px solid var(--line);border-radius:999px;padding:6px 11px;font-size:13px;background:#fff;min-height:36px}.lab-check{display:flex;gap:8px;align-items:flex-start;font-size:13px;margin-top:12px;line-height:1.6}.lab-check input{margin-top:4px;flex:none}
  <aside class="left"><button class="write" data-tour="emu-give" data-compose data-i18n="k.write">＋ 知識を届ける</button><div class="side-me" id="sideMe" hidden><button type="button" class="side-me-btn" id="sideTasks" aria-label="自分の宿題" title="自分の宿題"><span class="side-me-avatar side-me-icon" aria-hidden="true">✓</span><span class="side-me-label">自分の宿題</span></button><button type="button" class="side-me-btn" id="sideReizo" aria-label="冷蔵庫くんのガイド・聞く・頼む" title="冷蔵庫くんのガイド・聞く・頼む"><img src="/assets/mascot.jpg" alt=""><span class="side-me-label">冷蔵庫くん</span></button><button type="button" class="side-me-btn" id="sideProfile" aria-label="プロフィール" title="プロフィール" aria-haspopup="menu" aria-expanded="false"><span class="side-me-avatar" id="sideProfileAvatar" aria-hidden="true">👤</span><span class="side-me-label" id="sideProfileName">プロフィール</span></button></div></aside>
