<div class="overlay" id="composer" role="dialog" aria-modal="true" aria-labelledby="composerTitle" aria-hidden="true"><form class="modal" id="composeForm"><button class="close" type="button" data-close aria-label="閉じる" data-i18n-aria="k.close">×</button><p class="eyebrow">SHARE YOUR EXPERIENCE</p><h2 id="composerTitle" data-i18n="k.composerTitle">体験を、誰かの知識へ。</h2><p class="locked-note" id="editingDraftNote" hidden></p><div class="choices" id="composeThemes"></div><div class="field"><label for="title" data-i18n="k.field.title">タイトル</label><input id="title" maxlength="160" required placeholder="何を知識として届けますか？" data-i18n-placeholder="k.field.titlePlaceholder"><p class="locked-note" id="titleLockedNote" hidden></p></div><div class="field"><label for="body" data-i18n="k.field.body">体験から得たこと</label><textarea id="body" maxlength="5000" required placeholder="状況、試したこと、分かったこと、注意点を書いてください" data-i18n-placeholder="k.field.bodyPlaceholder"></textarea><div style="display:flex;flex-wrap:wrap;align-items:center;gap:0"><small style="width:100%;margin-top:8px;color:#8a8070;font-size:12px">🧊 書き方に困った？そんな時は、テンプレートを使用しよう！</small><button type="button" data-body-template="four" style="width:auto;max-width:max-content;justify-self:start;align-self:flex-start;display:inline-block;margin:8px 6px 0 0;border:1px dashed #d8b98a;background:#fff8ee;color:#8a4b00;border-radius:999px;padding:7px 14px;font:inherit;font-size:13px;font-weight:700;cursor:pointer">テンプレート①：何があった → 何をした → どうなった → 次の人へ</button><button type="button" data-body-template="three" style="width:auto;max-width:max-content;justify-self:start;align-self:flex-start;display:inline-block;margin:8px 6px 0 0;border:1px dashed #d8b98a;background:#fff8ee;color:#8a4b00;border-radius:999px;padding:7px 14px;font:inherit;font-size:13px;font-weight:700;cursor:pointer">テンプレート②：どうしたの？ → どうしたいの？ → どうしようか？</button></div><div style="margin-top:10px"><button type="button" data-proofread style="width:auto;max-width:max-content;justify-self:start;align-self:flex-start;display:inline-block;border:0;background:#1f6f5c;color:#fff;border-radius:999px;padding:8px 16px;font:inherit;font-size:13px;font-weight:700;cursor:pointer">🧊 冷蔵庫くんに整えてもらう</button><small data-proofread-note style="display:block;margin-top:4px;color:#8a8070;font-size:12px">冷蔵庫くんが校正をしてくれるよ！臆さず書いてみよう。1日3回まで。</small><div data-proofread-panel hidden style="margin-top:10px;border:1px solid #cfe3da;background:#f3faf6;border-radius:12px;padding:12px"><div data-proofread-msg style="font-size:13px;font-weight:700;color:#1f6f5c"></div><div data-proofread-title style="margin-top:8px;font-weight:700;white-space:pre-wrap;overflow-wrap:anywhere"></div><div data-proofread-lab style="margin-top:6px;font-size:12px;color:#1f6f5c;white-space:pre-wrap;overflow-wrap:anywhere"></div><div data-proofread-body style="margin-top:6px;font-size:14px;line-height:1.8;white-space:pre-wrap;overflow-wrap:anywhere;max-height:260px;overflow:auto;background:#fff;border-radius:8px;padding:10px"></div><div style="margin-top:10px"><button type="button" data-proofread-use style="width:auto;display:inline-block;border:0;background:#1f6f5c;color:#fff;border-radius:999px;padding:7px 14px;font:inherit;font-size:13px;font-weight:700;cursor:pointer;margin-right:6px">この案を使う</button><button type="button" data-proofread-cancel style="width:auto;display:inline-block;border:1px solid #cfe3da;background:#fff;color:#1f6f5c;border-radius:999px;padding:7px 14px;font:inherit;font-size:13px;font-weight:700;cursor:pointer">やめる（今のままにする）</button></div></div></div></div><script>
/* 書き方の型（11/9）。冷蔵庫くんが案内している書き方を、そのまま本文に入れる。投稿のハードルを下げるため。
   four  … 4行の型（何があった・何をした・どうなった・次の人へひとこと）
   three … 3つの問い（どうしたの？＝事実・どうしたいの？＝願望・どうしようか？＝行動）。#000 の「今後の人生について」と同じ問い方。
   型の見出しだけで中身が空のまま公開しようとしたら、ひとこと止める（ブラウザの入力チェックで出す）。 */
(function(){
  var TEMPLATES={
    four:['【何があった？】','【何をした？】','【どうなった？】','【次の人へひとこと】'],
    three:['【どうしたの？（事実）】','【どうしたいの？（願望）】','【どうしようか？（行動）】']
  };
  var ALL=TEMPLATES.four.concat(TEMPLATES.three);
  function onlyHeads(v){var t=v;ALL.forEach(function(h){t=t.split(h).join('');});return !t.trim()&&ALL.some(function(h){return v.indexOf(h)>=0;});}
  function check(){var b=document.getElementById('body');if(b)b.setCustomValidity(onlyHeads(b.value)?'型の中に、あなたの体験を書いてください':'');}
  document.addEventListener('click',function(e){
    var t=e.target&&e.target.closest&&e.target.closest('[data-body-template]');if(!t)return;
    var heads=TEMPLATES[t.getAttribute('data-body-template')];if(!heads)return;
    var b=document.getElementById('body');if(!b||b.readOnly)return;
    if(b.value.trim()&&!confirm('いまの本文の下に、型を足しますか？'))return;
    var start=b.value.trim()?b.value.replace(/\s+$/,'')+'\n\n':'';
    b.value=start+heads.map(function(h){return h+'\n';}).join('\n');
    var pos=start.length+heads[0].length+1;b.focus();b.setSelectionRange(pos,pos);
    b.dispatchEvent(new Event('input',{bubbles:true}));check();
  });
  document.addEventListener('input',function(e){if(e.target&&e.target.id==='body')check();});

  /* 冷蔵庫くんに整えてもらう（11/9）。親（Emu）がログインの鍵を持っているので、親に頼んで結果を受け取る。
     返ってきた案は見せるだけ。「この案を使う」を押したときだけ本文（とタイトルが空ならタイトル）に入れる。 */
  var pending=null,suggestion=null;
  /* 「詳しく整理する」の分類の候補（11/9）。AI はこの中からだけ選ぶ。読めなければ本文の校正だけにする。 */
  async function labTerms(){
    try{if(!state.labTerms){var r=await fetch('/api/knowledge-lab/taxonomy');var j=await r.json();if(r.ok)state.labTerms=Array.isArray(j)?j:(j.items||[]);}}catch(e){}
    var out={};(state.labTerms||[]).forEach(function(t){if(!t||!LAB_AXES[t.axis]||t.active===false||t.mergedInto)return;(out[t.axis]=out[t.axis]||[]).push([t.id,t.label]);});
    return out;
  }
  function labSummary(lab){
    var parts=[];var byId={};(state.labTerms||[]).forEach(function(t){byId[t.id]=t.label;});
    Object.keys(lab.facets||{}).forEach(function(a){var names=(lab.facets[a]||[]).map(function(id){return byId[id]||id;});if(names.length)parts.push((LAB_AXES[a]||a)+'：'+names.join('・'));});
    if(lab.period)parts.push('経験した時期：'+lab.period);
    var filled=[lab.happened?'何が起きたか':'',lab.learned?'学んだこと':'',lab.advice?'助言・注意点':''].filter(Boolean);
    if(filled.length)parts.push(filled.join('・')+'も下書きします');
    return parts.length?'📚 詳しく整理する（Knowledge Lab）も入れます\n'+parts.join('\n'):'';
  }
  /* 本人が入れたものは上書きしない。空の欄と、まだ選んでいない軸だけに入れる。 */
  function applyLab(lab){
    if(!lab||typeof fillLab!=='function'||typeof labPayload!=='function')return;
    var cur=labPayload()||{facets:typeof labFacetValue==='function'?labFacetValue():{},period:'',happened:'',learned:'',advice:'',sources:'',verification:'self-reported',aiUseConsent:false};
    var merged=Object.assign({},cur,{facets:Object.assign({},cur.facets||{})});
    Object.keys(lab.facets||{}).forEach(function(a){if(!(merged.facets[a]||[]).length)merged.facets[a]=lab.facets[a].slice();});
    ['period','happened','learned','advice'].forEach(function(k){if(!String(merged[k]||'').trim()&&lab[k])merged[k]=lab[k];});
    fillLab(merged);var more=document.getElementById('labMore');if(more)more.open=true;
  }
  function q(sel){return document.querySelector(sel);}
  function show(msg,sug){var p=q('[data-proofread-panel]');if(!p)return;p.hidden=false;q('[data-proofread-msg]').textContent=msg;
    q('[data-proofread-title]').textContent=(sug&&sug.title?'タイトル案：'+sug.title:'')+(sug&&sug.tags&&sug.tags.length?(sug.title?'\n':'')+'タグ案：'+sug.tags.join(', '):'');q('[data-proofread-body]').textContent=sug?sug.body:'';
    q('[data-proofread-body]').style.display=sug?'block':'none';q('[data-proofread-lab]').textContent=sug&&sug.lab?labSummary(sug.lab):'';q('[data-proofread-use]').style.display=sug?'inline-block':'none';
    q('[data-proofread-cancel]').textContent=sug?'やめる（今のままにする）':'閉じる';}
  function busy(on){var b=q('[data-proofread]');if(b){b.disabled=on;b.textContent=on?'🧊 冷蔵庫くんが読んでいます…':'🧊 冷蔵庫くんに整えてもらう';}}
  document.addEventListener('click',function(e){
    var t=e.target&&e.target.closest?e.target:null;if(!t)return;
    if(t.closest('[data-proofread]')){
      var body=(q('#body')||{}).value||'';if(!body.trim()||onlyHeads(body)){show('本文を書いてから押してね🧊',null);return;}
      if(pending)return;var id='p'+Date.now()+Math.random().toString(36).slice(2,8);pending=id;busy(true);suggestion=null;
      labTerms().then(function(terms){if(pending!==id)return;
        try{window.parent.postMessage({type:'emu-knowledge-proofread',requestId:id,title:(q('#title')||{}).value||'',body:body,terms:terms},location.origin);}catch(err){pending=null;busy(false);}});
      setTimeout(function(){if(pending){pending=null;busy(false);show('うまくつながらなかったみたい🧊 もう一度押してね。',null);}},60000);
      return;
    }
    if(t.closest('[data-proofread-use]')&&suggestion){
      var b=q('#body'),ti=q('#title');
      if(b&&!b.readOnly){b.value=suggestion.body;b.dispatchEvent(new Event('input',{bubbles:true}));}
      if(ti&&!ti.readOnly&&!ti.value.trim()&&suggestion.title){ti.value=suggestion.title;ti.dispatchEvent(new Event('input',{bubbles:true}));}
      /* タグも、空のときだけ入れる（11/9）。本人が書いたタグは上書きしない。 */
      var tg=q('#tags');if(tg&&!tg.readOnly&&!tg.value.trim()&&suggestion.tags&&suggestion.tags.length){tg.value=suggestion.tags.join(', ');tg.dispatchEvent(new Event('input',{bubbles:true}));}
      applyLab(suggestion.lab);check();q('[data-proofread-panel]').hidden=true;suggestion=null;return;
    }
    if(t.closest('[data-proofread-cancel]')){q('[data-proofread-panel]').hidden=true;suggestion=null;}
  });
  window.addEventListener('message',function(e){
    if(e.origin!==location.origin||e.source!==window.parent)return;var m=e.data||{};
    if(m.type!=='emu-knowledge-proofread-result'||!pending||m.requestId!==pending)return;
    pending=null;busy(false);
    var left=typeof m.remaining==='number'?'（今日あと'+m.remaining+'回）':'';
    if(!m.ok){show(m.error||'うまく整えられなかったみたい🧊',null);return;}
    suggestion={title:String(m.title||''),body:String(m.body||''),tags:Array.isArray(m.tags)?m.tags.map(String).slice(0,5):[],lab:m.lab&&typeof m.lab==='object'?m.lab:null};
    show('🧊 こう整えてみたよ'+(m.note?'：'+m.note:'')+left,suggestion);
  });
})();
