window.emuSideIdentity=function(me){const box=$('#sideProfileAvatar'),nm=$('#sideProfileName'),btn=$('#sideProfile');if(!box||!nm||!btn)return;const on=!!(me&&me.signedIn),name=String(me&&me.name||'').slice(0,60),av=String(me&&me.avatar||'');nm.textContent=on?(name||'Emuer'):'ログイン・プロフィール';box.textContent='';if(on&&av.length<=300000&&/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+\/]+=*$/.test(av)){const img=document.createElement('img');img.alt='';img.onerror=()=>{box.textContent=(name||'E').slice(0,1)};img.src=av;box.appendChild(img)}else box.textContent=on?(name||'E').slice(0,1):'👤';btn.title=on?'プロフィール：'+(name||'Emuer'):'プロフィール';btn.setAttribute('aria-label',btn.title)};
