const LAB_AXES={field:'分野',industry:'業種',occupation:'職業',experience:'経験の種類',purpose:'目的',kind:'知識の形式',genre:'ジャンル',difficulty:'難易度',audience:'対象者',period:'経験した時期'};state.labTerms=null;state.labPending={};state.labRendered=false;
function renderLabFacets(value){value=value||{};const terms=state.labTerms||[];$('#labFacets').innerHTML=Object.keys(LAB_AXES).map(axis=>{const t=terms.filter(x=>x.axis===axis&&((x.active!==false&&!x.mergedInto)||(value[axis]||[]).includes(x.id)));const n=(value[axis]||[]).length;return t.length?`<details class="lab-axis" data-lab-axis="${axis}"${axis==='field'||n?' open':''}><summary>${esc(LAB_AXES[axis])}（複数可）<small data-lab-count>${n?n+'件選択':''}</small></summary><div class="opts">${t.map(x=>`<label><input type="checkbox" value="${esc(x.id)}"${(value[axis]||[]).includes(x.id)?' checked':''}>${esc(x.label)}</label>`).join('')}</div></details>`:''}).join('');$('#labFacets').querySelectorAll('.lab-axis').forEach(d=>d.addEventListener('change',()=>{const k=d.querySelectorAll('input:checked').length;d.querySelector('[data-lab-count]').textContent=k?k+'件選択':''}));state.labRendered=true}
async function loadLabFacets(){if(state.labRendered)return;if(!state.labTerms){$('#labFacets').innerHTML='<p class="locked-note">分類を読み込んでいます…</p>';try{const r=await fetch('/api/knowledge-lab/taxonomy');const j=await r.json();if(!r.ok)throw new Error('taxonomy');state.labTerms=Array.isArray(j)?j:(j.items||[])}catch(e){$('#labFacets').innerHTML='<p class="locked-note">分類を読み込めませんでした。時期や学んだことは、このまま残せます。</p>';return}}if(!state.labRendered)renderLabFacets(state.labPending)}
function labFacetValue(){if(!state.labRendered)return {...(state.labPending||{})};const v={};document.querySelectorAll('#labFacets [data-lab-axis]').forEach(f=>{const ids=[...f.querySelectorAll('input:checked')].map(i=>i.value);if(ids.length)v[f.dataset.labAxis]=ids});return v}
function labPayload(){const v={facets:labFacetValue(),period:$('#labPeriod').value.trim(),happened:$('#labHappened').value.trim(),learned:$('#labLearned').value.trim(),advice:$('#labAdvice').value.trim(),sources:$('#labSources').value.trim(),verification:$('#labVerification').value,aiUseConsent:true};return(Object.keys(v.facets).length||v.period||v.happened||v.learned||v.advice||v.sources||v.verification!=='self-reported')?v:null}
function fillLab(lab){lab=lab&&typeof lab==='object'?lab:{};$('#labPeriod').value=String(lab.period||'');$('#labHappened').value=String(lab.happened||'');$('#labLearned').value=String(lab.learned||'');$('#labAdvice').value=String(lab.advice||'');$('#labSources').value=String(lab.sources||'');$('#labVerification').value=['self-reported','tested-by-author','in-progress','needs-update'].includes(lab.verification)?lab.verification:'self-reported';$('#labAIConsent').checked=lab.aiUseConsent===true;state.labPending=lab.facets&&typeof lab.facets==='object'?lab.facets:{};state.labRendered=false;$('#labFacets').innerHTML='';if(labPayload()){$('#labMore').open=true;loadLabFacets()}}
